window.MG_LAZY_DATA["data/lazy/resources/soft-v29-092-bdd39abc8905415d.json"]={sha256:"bdd39abc8905415dc3d244ac334a7e6d2ade34ba96a1f70e6d36697d89e45120",value:{"sources":[{"id":"v29-case-38a08784d213b55e","url":"https://www.sqlite.org/queryplanner.html","title":"SQLite query planner","titleEn":"SQLite query planner","publisher":"SQLite","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"soft-v29-092","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"soft-v29-092","related":[{"id":"soft-v29-093","referenceUrls":["https://www.sqlite.org/queryplanner.html"],"title":"SQLite：covering index 與回表成本","titleEn":"SQLite: covering indexes and table-lookup cost","why":"用兩課的可觀察驗收條件比較模型邊界：比較 (department,score) 索引對雙條件查詢與只查 score 的差異。 驗收紀錄必須包含通過/失敗、重現方式和剩餘限制；只對已檢查的模型範圍作結論。","whyEn":"Compare model boundaries using observable acceptance criteria: Compare a (department,score) index for two-column predicates versus score-only queries. Acceptance includes pass/fail,reproduction instructions and remaining limits; conclusions stay within the checked model.","difference":"將查詢所需欄位加入索引，量化避免回表的教學成本而不誤當實測加速。","differenceEn":"Include projected fields in an index and quantify modeled avoided lookups without claiming measured speedup.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["字典序索引先按第一欄分段，再按第二欄排序；不同查詢可利用的連續範圍不同。 教學基準：1000/10 = 100 department rows；第二檢核：20/1000*100 = 2 whole-table selectivity percent。逐項保留單位、分母、排序或時間界線。 先手算或逐事件枚舉，再使用SQL、試算表或本機腳本重算，保存中間狀態。","Covering index 能從索引取得所需欄位；索引變寬同時增加空間與維護成本。 教學基準：1+40*0.2 = 9 non-covering modeled ms；第二檢核：1 = 1 covering modeled ms。逐項保留單位、分母、排序或時間界線。 先手算或逐事件枚舉，再使用SQL、試算表或本機腳本重算，保存中間狀態。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Lexicographic indexes group by the first column and sort by the second; queries expose different contiguous ranges. Teaching baseline: 1000/10 = 100 department rows; second check: 20/1000*100 = 2 whole-table selectivity percent. Retain units,denominators,ordering and time boundaries. Enumerate by hand before using SQL,a spreadsheet or a local script; preserve intermediate states.","A covering index supplies required fields directly,while increased width adds space and maintenance cost. Teaching baseline: 1+40*0.2 = 9 non-covering modeled ms; second check: 1 = 1 covering modeled ms. Retain units,denominators,ordering and time boundaries. Enumerate by hand before using SQL,a spreadsheet or a local script; preserve intermediate states.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"soft-v29-102","referenceUrls":["https://vs.inf.ethz.ch/publ/papers/VirtTimeGlobStates.pdf","https://lamport.azurewebsites.net/pubs/time-clocks.pdf"],"title":"Vector clock：並行版本與逐分量比較","titleEn":"Vector clocks: concurrent versions and componentwise order","why":"用兩課的可觀察驗收條件比較模型邊界：比較 (department,score) 索引對雙條件查詢與只查 score 的差異。 驗收紀錄必須包含通過/失敗、重現方式和剩餘限制；只對已檢查的模型範圍作結論。","whyEn":"Compare model boundaries using observable acceptance criteria: Compare a (department,score) index for two-column predicates versus score-only queries. Acceptance includes pass/fail,reproduction instructions and remaining limits; conclusions stay within the checked model.","difference":"用二節點版本向量辨識先後與並行，避免以字典序掩蓋衝突。","differenceEn":"Use two-node vectors to distinguish precedence from concurrency rather than hiding conflicts by lexicographic sorting.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["字典序索引先按第一欄分段，再按第二欄排序；不同查詢可利用的連續範圍不同。 教學基準：1000/10 = 100 department rows；第二檢核：20/1000*100 = 2 whole-table selectivity percent。逐項保留單位、分母、排序或時間界線。 先手算或逐事件枚舉，再使用SQL、試算表或本機腳本重算，保存中間狀態。","向量逐分量≤且至少一個\u003c才表示先後；彼此各有較大分量則並行，merge 取逐分量 max。 教學基準：max(2,1)+max(0,1) = 3 merged component sum；第二檢核：max(0,1)+1 = 2 node-2 component after write。逐項保留單位、分母、排序或時間界線。 先手算或逐事件枚舉，再使用SQL、試算表或本機腳本重算，保存中間狀態。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Lexicographic indexes group by the first column and sort by the second; queries expose different contiguous ranges. Teaching baseline: 1000/10 = 100 department rows; second check: 20/1000*100 = 2 whole-table selectivity percent. Retain units,denominators,ordering and time boundaries. Enumerate by hand before using SQL,a spreadsheet or a local script; preserve intermediate states.","Componentwise \u003c= with one strict component establishes order; crossed components mean concurrency and merge takes componentwise maxima. Teaching baseline: max(2,1)+max(0,1) = 3 merged component sum; second check: max(0,1)+1 = 2 node-2 component after write. Retain units,denominators,ordering and time boundaries. Enumerate by hand before using SQL,a spreadsheet or a local script; preserve intermediate states.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v29-case-38a08784d213b55e","url":"https://www.sqlite.org/queryplanner.html","title":"SQLite query planner","titleEn":"SQLite query planner","publisher":"SQLite","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v29-case-60f7cf4e0679c76a","url":"https://lamport.azurewebsites.net/pubs/time-clocks.pdf","title":"Time, Clocks, and the Ordering of Events in a Distributed System","titleEn":"Time, Clocks, and the Ordering of Events in a Distributed System","publisher":"Leslie Lamport","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v29-case-9fe3ee40fa04b512","url":"https://vs.inf.ethz.ch/publ/papers/VirtTimeGlobStates.pdf","title":"Virtual Time and Global States of Distributed Systems","titleEn":"Virtual Time and Global States of Distributed Systems","publisher":"Friedemann Mattern","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
